// /reads and /reads/<slug> — the essay series.
//
// Each essay page is static HTML carrying the essay's opening (generated by
// scripts/build-reads.js). This swaps in the full text:
//   - a signed-in member reads it straight from Firestore
//     (reads/{series}/essays/{slug}, readable by any signed-in account);
//   - a signed-out reader gives a name and email, and the claimRead function
//     creates their free portal account and returns the essay in one step.
// A reader who unlocked an essay on this device is remembered, so the next
// essay opens without the form.

import { onAuthReady } from './auth.js';
import { db, functions, firebaseReady } from './firebase.js';
import { httpsCallable } from 'https://www.gstatic.com/firebasejs/10.12.0/firebase-functions.js';
import { doc, getDoc } from 'https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js';

const $ = (id) => document.getElementById(id);
const CLAIM_KEY = '1p_reads_reader';
const EMAIL_RE = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

function readConfig() {
  try { return JSON.parse($('r-config').textContent); } catch (e) { return null; }
}
function savedReader() {
  try {
    const r = JSON.parse(localStorage.getItem(CLAIM_KEY) || 'null');
    return r && r.name && EMAIL_RE.test(r.email) ? r : null;
  } catch (e) { return null; }
}
function saveReader(r) {
  try { localStorage.setItem(CLAIM_KEY, JSON.stringify(r)); } catch (e) {}
}

function showAccount(signedIn) {
  document.querySelectorAll('[data-auth]').forEach((el) => {
    el.hidden = (el.dataset.auth === 'in') !== signedIn;
  });
}

function unlock(html, note) {
  const body = $('r-body');
  // The full text starts with the same blocks as the preview, so the reader
  // carries on from the paragraph that was fading out, and the welcome note
  // lands there, where they are looking, not at the top of the page.
  const seen = body.children.length;
  body.innerHTML = html;
  body.classList.remove('r-fade');
  const gate = $('r-gate');
  if (gate) gate.remove();
  if (note) {
    const p = document.createElement('p');
    p.className = 'r-note';
    p.textContent = note;
    body.insertBefore(p, body.children[seen] || null);
  }
  const end = $('r-end');
  if (end) end.hidden = false;
}

function noteFor(status) {
  if (status === 'created') return 'Welcome to The One Percent. Your free portal account is ready, and we emailed you a link to set your password.';
  if (status === 'existing') return 'Welcome back. This essay is open to you as a member. Log in any time to read in your portal.';
  return '';
}

async function claim(cfg, reader) {
  const call = () => httpsCallable(functions, 'claimRead')({
    name: reader.name, email: reader.email, series: cfg.series, slug: cfg.slug
  });
  try {
    return (await call()).data;
  } catch (e) {
    const code = String((e && e.code) || '').replace(/^functions\//, '');
    if (code === 'invalid-argument') throw new Error(e.message || 'Please check your name and email.');
    if (code === 'resource-exhausted') throw new Error('Too many tries from here. Please wait a few minutes and try again.');
    // One retry for a cold start or a dropped connection.
    await new Promise((r) => setTimeout(r, 1200));
    try { return (await call()).data; } catch (e2) {
      throw new Error('Something went wrong on our side. Please try again.');
    }
  }
}

function wireGate(cfg) {
  const form = $('r-form');
  if (!form) return;
  const err = $('r-err');
  const go = $('r-go');
  form.addEventListener('submit', async (ev) => {
    ev.preventDefault();
    err.textContent = '';
    const name = $('r-name').value.trim();
    const email = $('r-email').value.trim().toLowerCase();
    if (!name) { err.textContent = 'Please enter your first name.'; $('r-name').focus(); return; }
    if (!EMAIL_RE.test(email)) { err.textContent = 'Please enter a valid email.'; $('r-email').focus(); return; }
    if (!firebaseReady) { err.textContent = 'Sign up is unavailable right now. Please refresh and try again.'; return; }
    go.disabled = true;
    go.textContent = 'Opening the essay...';
    try {
      const res = await claim(cfg, { name, email });
      saveReader({ name, email });
      unlock(res.html, noteFor(res.status));
      if (typeof gtag === 'function') gtag('event', 'sign_up', { method: 'reads', essay: cfg.slug });
    } catch (e) {
      err.textContent = e.message;
      go.disabled = false;
      go.textContent = 'Keep reading, free';
    }
  });
}

function wireShare(cfg) {
  const btn = $('r-share');
  if (!btn) return;
  btn.addEventListener('click', async () => {
    const url = location.origin + location.pathname;
    if (navigator.share) {
      try { await navigator.share({ title: cfg.title, url }); } catch (e) {}
      return;
    }
    try {
      await navigator.clipboard.writeText(url);
      btn.textContent = 'Link copied';
      setTimeout(() => { btn.textContent = 'Share'; }, 1800);
    } catch (e) {}
  });
}

function wireProgress() {
  const bar = $('r-progress');
  const article = document.querySelector('article');
  if (!bar || !article) return;
  // On a phone the bar slides away while the reader scrolls down into the
  // essay and comes back the moment they scroll up.
  const navEl = document.querySelector('.r-nav');
  let lastY = window.scrollY;
  const update = () => {
    const y = window.scrollY;
    if (navEl) navEl.classList.toggle('away', y > 140 && y > lastY + 2);
    if (Math.abs(y - lastY) > 2) lastY = y;
    const rect = article.getBoundingClientRect();
    const total = rect.height - window.innerHeight;
    const done = total > 0 ? Math.min(1, Math.max(0, -rect.top / total)) : 0;
    bar.style.width = `${(done * 100).toFixed(1)}%`;
  };
  window.addEventListener('scroll', update, { passive: true });
  window.addEventListener('resize', update);
  update();
}

async function main() {
  const cfg = readConfig();
  if (cfg) { wireGate(cfg); wireShare(cfg); wireProgress(); }

  const user = firebaseReady ? await onAuthReady() : null;
  showAccount(!!user);
  if (!cfg) return;

  if (user) {
    try {
      const snap = await getDoc(doc(db, 'reads', cfg.series, 'essays', cfg.slug));
      if (snap.exists() && snap.data().html) { unlock(snap.data().html); return; }
    } catch (e) {
      console.warn('[reads] full text unavailable', e);
    }
    // Signed in but the direct read failed: ask the server, which knows the
    // caller from their sign-in and needs no name or email.
    try {
      const res = await claim(cfg, { name: user.displayName || '', email: user.email || '' });
      unlock(res.html);
    } catch (e) {
      const gate = $('r-gate');
      if (gate) gate.innerHTML = '<h2>This essay is being updated</h2><p class="lead">Check back in a few minutes.</p>';
    }
    return;
  }

  const reader = savedReader();
  if (reader) {
    try {
      const res = await claim(cfg, reader);
      unlock(res.html);
    } catch (e) {
      // Keep the preview and the form; the reader can try again by hand.
      $('r-name').value = reader.name;
      $('r-email').value = reader.email;
    }
  }
}

main();
